const enfermedadData=[{"disease":"Todos dijeron que sí y nunca pasó nada","characteristic":"No quedó nada por escrito y cambió el funcionario","opts":["No quedó nada por escrito y cambió el funcionario","El proyecto no era bueno","Faltó dinero","La reunión fue muy corta"]},{"disease":"La autorización llegó de arriba y en el centro se usó a medias","characteristic":"Se saltó al director: una orden que él no quiere se cumple mal","opts":["Se saltó al director: una orden que él no quiere se cumple mal","Los maestros no sabían usarla","La autorización estaba mal redactada","Faltaron equipos"]},{"disease":"El permiso llegó en septiembre y no se usó","characteristic":"El calendario: el año escolar ya iba de salida","opts":["El calendario: el año escolar ya iba de salida","El permiso era falso","Nadie leyó el permiso","Cambió la ley"]},{"disease":"El material circula sin el nombre del autor","characteristic":"La autoría no se pidió por escrito antes de entregarlo","opts":["La autoría no se pidió por escrito antes de entregarlo","Alguien lo robó a propósito","El diseño no tenía espacio","Se perdió el archivo original"]},{"disease":"Dos centros quedaron sin poder usar otras herramientas","characteristic":"Se firmó exclusividad, y la cumplen los que no firmaron","opts":["Se firmó exclusividad, y la cumplen los que no firmaron","Los equipos eran incompatibles","Los maestros no quisieron","La departamental lo prohibió"]},{"disease":"El proyecto quedó marcado como de un partido","characteristic":"Se aceptó un patrocinio sin reglas publicadas para todos","opts":["Se aceptó un patrocinio sin reglas publicadas para todos","Alguien habló mal del proyecto","Se publicó en la temporada equivocada","El logo era muy grande"]}];
let enferIdx=0,enferDone=false;
function showEnfer(){enferDone=false;if(enferIdx>=enfermedadData.length){const el=document.getElementById('enferDisease');if(el)el.textContent='🎉 ¡Completado!';const opts=document.getElementById('enferOpts');if(opts)opts.innerHTML='';return;}const d=enfermedadData[enferIdx];const prog=document.getElementById('enferProg');if(prog)prog.textContent=`${enferIdx+1} de ${enfermedadData.length}`;const dis=document.getElementById('enferDisease');if(dis)dis.textContent=d.disease;const opts=document.getElementById('enferOpts');if(!opts)return;opts.innerHTML='';_shuffle([...d.opts]).forEach(opt=>{const b=document.createElement('button');b.className='qz-opt';b.textContent=opt;b.onclick=()=>checkEnfer(opt,b,d);opts.appendChild(b);});const fbEl=document.getElementById('fbEnfer');if(fbEl)fbEl.classList.remove('show');}
function checkEnfer(opt,btn,d){if(enferDone)return;enferDone=true;document.querySelectorAll('#enferOpts .qz-opt').forEach(b=>{if(b.textContent===d.characteristic)b.classList.add('correct');else if(b===btn&&b.textContent!==d.characteristic)b.classList.add('wrong');});const isOk=opt===d.characteristic;if(isOk){fb('fbEnfer','¡Correcto! +3 XP',true);if(!xpTracker.wgt.has('enfer_'+enferIdx)){xpTracker.wgt.add('enfer_'+enferIdx);pts(3);}sfx('ok');}else{fb('fbEnfer','Correcto: '+d.characteristic,false);sfx('no');}setTimeout(()=>{enferIdx++;showEnfer();},1800);}
function resetEnfer(){sfx('click');enferIdx=0;showEnfer();}

