function evalSwitchMode(mode){
  sfx('click');
  const cWrap=document.getElementById('evalConceptWrap'),critWrap=document.getElementById('evalCritWrap');
  const cBtn=document.getElementById('evalModeBtnConcept'),critBtn=document.getElementById('evalModeBtnCrit');
  if(mode==='crit'){
    cWrap.style.display='none';critWrap.style.display='block';
    cBtn.classList.remove('active');cBtn.setAttribute('aria-selected','false');
    critBtn.classList.add('active');critBtn.setAttribute('aria-selected','true');
    if(!window._evalCritData)genEvalCrit();
  }else{
    critWrap.style.display='none';cWrap.style.display='block';
    critBtn.classList.remove('active');critBtn.setAttribute('aria-selected','false');
    cBtn.classList.add('active');cBtn.setAttribute('aria-selected','true');
  }
}

const critCaseBank=[{"txt":"Una oficina del nivel central propone incorporar las misiones de M.E.T.A.S al material de apoyo de todo un departamento. No hay pago; hay alcance, y quieren empezar el próximo mes."},{"txt":"En año de campaña, alguien ofrece imprimir 5.000 fichas para escuelas del municipio. La única condición es su fotografía y su nombre en la portada."},{"txt":"El director de un centro donde ya se usa la aplicación decide que no se use más en horario de clase, sin dar una razón técnica."},{"txt":"Una organización ofrece 300 tabletas para tres escuelas a cambio de que en esos centros solo se use su plataforma durante dos años."},{"txt":"Una dirección departamental quiere el sistema en 200 centros de inmediato, con capacitación y soporte a cargo del proyecto y sin ningún pago."},{"txt":"Una escuela privada ofrece pagar una cuota mensual con la condición de que ningún otro centro de la ciudad pueda usar el sistema."}];
const critCaseQuestions=["1. ¿Quién decide de verdad aquí, quién puede trabar y quién paga?","2. ¿Qué mete esta oferta y qué saca, más allá del dinero?","3. Escribe en 3-4 frases la condición mínima con la que dirías que sí.","4. ¿Qué queda por escrito, quién lo firma y hasta cuándo dura?"];
const critCaseGuides=["Casi nunca es la misma persona: quien firma da validez, quien traba decide si de verdad ocurre, y quien paga marca las condiciones. Nombrar a los tres cambia la estrategia entera.","Lo que se saca casi nunca es dinero: es autoría, neutralidad, horas recurrentes, libertad de los centros o espacio de marca. Eso es lo que hay que poner en la balanza.","La condición mínima tiene que ser concreta y verificable: un crédito visible, un piloto de N centros, una fecha de revisión. «Que se porten bien» no es una condición.","Sin papel no hay acuerdo. Debe decir quiénes (la institución, no la persona), qué aporta cada uno, qué no incluye, de quién es el material y hasta cuándo dura."];

const critErrorBank=[{"txt":"\"Como la autorización viene de arriba, el director tiene que aceptarla y punto\".","g1":"El director maneja el día a día del centro: una orden que no quiere se cumple mal, tarde o a medias, sin desobedecer nunca.","g2":"Saltarse ese nivel gana el papel y pierde la ejecución. Se informa y se le da algo que él pueda mostrar como suyo."},{"txt":"\"Salimos con un sí de la reunión, ya está resuelto\".","g1":"Un sí verbal no obliga a quien llegue después al cargo, y los cambios de funcionario son frecuentes.","g2":"Se manda un correo el mismo día resumiendo lo acordado: ese correo es el acta, y cuesta cinco minutos."},{"txt":"\"Aceptamos la exclusividad porque el equipo hace falta de verdad\".","g1":"La exclusividad la firma quien recibe el equipo, pero la cumplen los centros y los maestros, que no participaron del trato.","g2":"Se puede aceptar el equipo sin aceptar la exclusividad: convivencia sí, monopolio no."},{"txt":"\"Mejor no publicamos reglas de patrocinio, para no cerrarle la puerta a nadie\".","g1":"Sin reglas, cada no es personal y cada sí es un precedente que el siguiente va a exigir.","g2":"Con reglas publicadas e iguales para todos, el no deja de ser contra alguien y pasa a ser la norma de la casa."},{"txt":"\"Doscientas escuelas de golpe es la oportunidad de la vida\".","g1":"Es una obligación recurrente sin ingreso: doscientos centros llamando a una sola persona.","g2":"Lo que no se puede sostener se sostiene mal, y el proyecto queda con fama de que no responde. Diez centros bien atendidos abren más puertas que doscientos mal atendidos."}];

const critDecisionBank=["La Secretaría quiere adoptar las misiones de M.E.T.A.S para un departamento entero: ¿qué se pide por escrito antes de entregar nada?","Un diputado ofrece imprimir 5.000 fichas con su cara en la portada en año electoral: ¿cómo se responde sin quemar el puente?","Un director prohíbe la aplicación en horario de clase: ¿qué se hace primero y a quién se le habla?","Una ONG da 300 tabletas a cambio de exclusividad por dos años en tres escuelas: ¿se acepta, con qué cambios?","Una departamental pide el sistema en 200 centros con soporte gratuito: ¿cuál es la contraoferta concreta?","La municipalidad ofrece imprimir material: ¿qué se le pide exactamente y en qué mes conviene pedirlo?","Una escuela privada paga por el sistema si nadie más en la ciudad lo usa: ¿qué parte de eso sí se puede vender?","Una maestra quiere presentar las misiones en la reunión de su distrito: ¿cómo se la apoya sin exponerla?"];
const critDecisionGuide="La decisión correcta sigue los principios de la casa: se identifica quién firma, quién traba y quién paga antes de responder; se empieza pequeño y reversible; nunca se compromete a terceros que no firmaron; la autoría y el uso se acuerdan antes de entregar, no después; y todo queda por escrito con la institución y no con la persona. Cuando la oferta es grande y urgente, esa combinación es justamente la señal para tomarse los días que hagan falta y responder con una condición concreta.";

const critCompareBank=[{"a":"Un piloto de diez centros con un docente enlace por zona.","b":"Doscientos centros de una vez, con soporte de una sola persona.","ga":"Caso A: se puede sostener, se aprende de los primeros y el crecimiento no depende de una persona.","gb":"Caso B: se ve grande el primer mes y al tercero el proyecto tiene fama de no responder."},{"a":"Adopción con crédito del autor y licencia escrita.","b":"Adopción rápida, sin papel, con la promesa de reconocerlo después.","ga":"Caso A: el material circula con nombre y se puede seguir usando en otros lados.","gb":"Caso B: lo adoptado tiende a quedarse sin autor, y reclamarlo después es una pelea que se pierde."},{"a":"Reglas de patrocinio publicadas e iguales para todos.","b":"Decidir caso por caso quién puede poner su logo.","ga":"Caso A: el no deja de ser personal y el proyecto no queda amarrado a ningún grupo.","gb":"Caso B: cada decisión crea un precedente y en año electoral eso se cobra."},{"a":"Mandar el mismo día un correo con lo acordado.","b":"Confiar en la buena relación con quien te recibió.","ga":"Caso A: hay constancia, y la constancia sobrevive al cambio de puesto.","gb":"Caso B: la relación es real y no obliga a nadie más; cuando esa persona se va, se empieza de cero."},{"a":"Pedirle a la municipalidad una impresión concreta y medible.","b":"Pedirle a la municipalidad \"apoyo para el proyecto\".","ga":"Caso A: es una petición que se puede aprobar, ejecutar y mostrar.","gb":"Caso B: sale bien la reunión y no sale nada más, porque nadie sabe qué aprobar."}];

const critCauseBank=[{"cause":"Se consigue la autorización departamental sin hablar con el director.","guide":"El papel llega y la ejecución no: el centro cumple a medias sin desobedecer nunca. Hay que volver al nivel que se saltó."},{"cause":"Se acepta un patrocinio político sin reglas publicadas.","guide":"El material queda marcado, y en los centros donde ese grupo no manda entra con desventaja. Además fija un precedente para el siguiente que ofrezca."},{"cause":"Se entrega el material para adopción sin acuerdo de autoría.","guide":"Circula sin nombre, y reclamarlo después es una pelea larga que casi nunca se gana."},{"cause":"Se firma exclusividad a cambio de equipo.","guide":"Los centros quedan amarrados por un trato que no firmaron, y el proyecto pierde la capacidad de crecer en esa zona."},{"cause":"Se acepta dar soporte a doscientos centros sin estructura.","guide":"La obligación es recurrente y el ingreso no existe: el servicio se degrada y la reputación se paga después."},{"cause":"La gestión se hace en septiembre, con el año escolar de salida.","guide":"Aunque salga todo bien, no hay tiempo de usarlo: el permiso rinde hasta el año siguiente, si es que sigue vigente."}];
const critEffectBank=[{"effect":"El piloto de diez centros terminó con tres directores pidiendo ampliarlo.","guide":"Empezar pequeño y reversible permitió que otros vieran resultados sin arriesgarse. El poder real trabajó a favor."},{"effect":"Cambió el director del centro y el acuerdo siguió vigente.","guide":"Estaba firmado con la institución, no con la persona, y había copia. Eso es exactamente lo que se busca."},{"effect":"Un candidato aceptó poner su logo en la contraportada sin molestarse.","guide":"Existían reglas publicadas e iguales para todos: el no fue de la norma, no de la persona, y el puente quedó abierto."},{"effect":"La alcaldía imprimió 300 fichas en dos semanas.","guide":"La petición era concreta, medible y le servía para mostrar obra. Las peticiones vagas no se aprueban, no porque no quieran."},{"effect":"El material se adoptó en el departamento y sigue llevando el nombre del autor.","guide":"La autoría se pidió por escrito antes de entregar nada. Después de entregar, ya no se pide: se reclama."},{"effect":"Se dijo que no a una oferta grande y la relación siguió buena.","guide":"Se rechazó la versión, no a la persona, y se ofreció una alternativa concreta. Casi ningún no bien hecho cierra una puerta."}];

function genEvalCrit(){
  sfx('click');
  _injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});const _sC=document.getElementById('evalCritFormaSel');if(_sC&&parseInt(_sC.value,10))evalCritFormNum=Math.min(EVAL_FORMAS,Math.max(1,parseInt(_sC.value,10)));const cf=evalCritFormNum;window._currentEvalCritForm=cf;const rngC=_evalRng(200000+cf);evalCritFormNum=(evalCritFormNum%EVAL_FORMAS)+1;_injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});saveProgress();
  document.getElementById('evalcrit-screen-title').textContent=`🧠 Simulacro de negociación · Forma ${cf} · Quién decide de verdad · Ruta del Poder Político`;
  evalCritAnsVisible=false;
  const out=document.getElementById('evalCritOut');out.innerHTML='';

  const kase=_rotaF(critCaseBank,cf);
  const s1=document.createElement('div');
  s1.innerHTML=`<div class="eval-section-title">I. Simulacro de Presión: la interpelación <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${kase.txt}</div>${critCaseQuestions.map((q,i)=>`<div class="crit-q-block"><div class="crit-q-label">${q}</div><textarea class="crit-textarea" rows="2" aria-label="${q}"></textarea><div class="crit-pauta">${critCaseGuides[i]}</div></div>`).join('')}<div class="crit-selfscore"><label for="critScore0">Obtenido:</label><input type="number" id="critScore0" class="crit-score-input" data-score="0" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s1);

  const err=_rotaF(critErrorBank,cf);
  const s2=document.createElement('div');
  s2.innerHTML=`<div class="eval-section-title">II. Corrige el error <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${err.txt}</div><p style="font-size:0.85rem;margin-bottom:0.5rem;">Identifica <strong>dos errores</strong> y corrígelos con tus propias palabras:</p><div class="crit-q-block"><div class="crit-q-label">Error 1 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 1 y su corrección"></textarea><div class="crit-pauta">${err.g1}</div></div><div class="crit-q-block"><div class="crit-q-label">Error 2 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 2 y su corrección"></textarea><div class="crit-pauta">${err.g2}</div></div><div class="crit-selfscore"><label for="critScore1">Obtenido:</label><input type="number" id="critScore1" class="crit-score-input" data-score="1" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s2);

  const dec=_rotaF(critDecisionBank,cf);
  const s3=document.createElement('div');
  s3.innerHTML=`<div class="eval-section-title">III. Toma de decisiones bajo presión <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${dec}</div><div class="crit-q-block"><div class="crit-q-label">¿Quién decide de verdad, qué se pide a cambio y con qué condición por escrito aceptarías? Explica por qué tu salida es mejor que aceptar completo o que rechazar de plano.</div><textarea class="crit-textarea" rows="4" aria-label="Recomendación y justificación"></textarea><div class="crit-pauta">${critDecisionGuide}</div></div><div class="crit-selfscore"><label for="critScore2">Obtenido:</label><input type="number" id="critScore2" class="crit-score-input" data-score="2" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s3);

  const cmp=_rotaF(critCompareBank,cf);
  const s4=document.createElement('div');
  s4.innerHTML=`<div class="eval-section-title">IV. Comparación razonada <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-compare-grid"><div class="crit-compare-box"><h5>Caso A</h5>${cmp.a}</div><div class="crit-compare-box"><h5>Caso B</h5>${cmp.b}</div></div><div class="crit-q-block"><div class="crit-q-label">1. ¿Qué gana cada caso y cuál aguanta un cambio de funcionario? 2. ¿Por qué no son el mismo caso?</div><textarea class="crit-textarea" rows="4" aria-label="Comparación razonada de los casos A y B"></textarea><div class="crit-pauta">Caso A: ${cmp.ga} · Caso B: ${cmp.gb} · ${cmp.gr}</div></div><div class="crit-selfscore"><label for="critScore3">Obtenido:</label><input type="number" id="critScore3" class="crit-score-input" data-score="3" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s4);

  const causes=_pickF(critCauseBank,2,rngC),effects=_pickF(critEffectBank,3,rngC);
  let ceRows='';
  causes.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Causa</span>${it.cause}</div><div class="crit-ce-cell"><span class="crit-ce-tag">Efecto</span><textarea class="crit-textarea" rows="2" aria-label="Efecto de: ${it.cause}" placeholder="Escribe el efecto..."></textarea></div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  effects.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell"><span class="crit-ce-tag">Causa</span><textarea class="crit-textarea" rows="2" aria-label="Causa de: ${it.effect}" placeholder="Escribe la causa..."></textarea></div><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Efecto</span>${it.effect}</div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  const s5=document.createElement('div');
  s5.innerHTML=`<div class="eval-section-title">V. Análisis de causas y efectos <span class="eval-pts">20 pts</span></div><div class="eval-item">${ceRows}<div class="crit-selfscore"><label for="critScore4">Obtenido:</label><input type="number" id="critScore4" class="crit-score-input" data-score="4" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s5);

  window._evalCritData={kase,err,dec,cmp,causes,effects};
  const totalPanel=document.createElement('div');totalPanel.id='evalCritTotalResult';totalPanel.className='crit-total-panel';totalPanel.innerHTML='<strong>🧮 Autoevaluación:</strong> responde cada sección, compara con la <em>Pauta</em> y anota tu puntaje (0–20) en cada casilla. Luego presiona <em>Calcular Total</em>.';out.appendChild(totalPanel);
  fin('s-evaluacion');
}
function toggleEvalCritAns(){evalCritAnsVisible=!evalCritAnsVisible;document.querySelectorAll('#evalCritOut .crit-pauta').forEach(el=>el.style.display=evalCritAnsVisible?'block':'none');sfx('click');}
function calcCritTotal(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  let total=0;
  document.querySelectorAll('#evalCritOut .crit-score-input').forEach(inp=>{let v=parseInt(inp.value)||0;v=Math.max(0,Math.min(20,v));inp.value=v;total+=v;});
  const panel=document.getElementById('evalCritTotalResult');
  if(panel){panel.className='crit-total-panel '+(total>=70?'eval-auto-pass':'eval-auto-risk');panel.innerHTML=`<strong>Puntaje total autoevaluado: ${total}/100</strong><br><em>Compara siempre tus respuestas con la Pauta antes de anotar el puntaje de cada sección.</em>`;}
  const formKey='crit_'+(window._currentEvalCritForm||1);
  if(total>=70){if(!xpTracker.wgt.has(formKey)){xpTracker.wgt.add(formKey);pts(8);}showToast('🎯 Simulacro de negociación: '+total+'/100');}
  else showToast('🧮 Puntaje registrado: '+total+'/100. ¡Sigue practicando!');
}
function printEvalCrit(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  const forma=window._currentEvalCritForm||1;const d=window._evalCritData;
  const lines=(n)=>Array(n).fill('<div class="ln"></div>').join('');
  let s1=`<div class="sec-title"><span>I. Simulacro de Presión: la interpelación</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.kase.txt}</p>`;
  critCaseQuestions.forEach(q=>{s1+=`<p class="crit-print-q">${q}</p>${lines(1)}`;});
  let s2=`<div class="sec-title"><span>II. Corrige el error</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.err.txt}</p><p class="crit-print-q">Identifica dos errores y corrígelos con tus propias palabras:</p><p class="crit-print-q"><strong>Error 1:</strong></p>${lines(1)}<p class="crit-print-q"><strong>Error 2:</strong></p>${lines(1)}`;
  let s3=`<div class="sec-title"><span>III. Toma de decisiones bajo presión</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.dec}</p><p class="crit-print-q">¿Quién decide de verdad, qué se pide a cambio y con qué condición por escrito aceptarías? Explica por qué tu salida es mejor que aceptar completo o que rechazar de plano.</p>${lines(2)}`;
  let s4=`<div class="sec-title"><span>IV. Comparación razonada</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><div class="crit-compare-print-grid"><div class="crit-compare-print-box"><strong>Caso A:</strong> ${d.cmp.a}</div><div class="crit-compare-print-box"><strong>Caso B:</strong> ${d.cmp.b}</div></div><p class="crit-print-q">1. ¿Qué gana cada caso y cuál aguanta un cambio de funcionario? 2. ¿Por qué no son el mismo caso?</p>${lines(2)}`;
  let ceTbl='<table class="crit-print-tbl"><tr><th>Causa</th><th>Efecto</th></tr>';
  d.causes.forEach(it=>{ceTbl+=`<tr><td>${it.cause}</td><td></td></tr>`;});
  d.effects.forEach(it=>{ceTbl+=`<tr><td></td><td>${it.effect}</td></tr>`;});
  ceTbl+='</table>';
  let s5=`<div class="sec-title"><span>V. Análisis de causas y efectos</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div>${ceTbl}`;
  let pR='';
  pR+=`<div class="p-sec"><div class="p-ttl">I. Caso</div>${critCaseQuestions.map((q,i)=>`<div class="p-crit-line"><strong>${i+1}.</strong> ${critCaseGuides[i]}</div>`).join('')}</div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">II. Corrige el error</div><div class="p-crit-line"><strong>Error 1:</strong> ${d.err.g1}</div><div class="p-crit-line"><strong>Error 2:</strong> ${d.err.g2}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">III. Toma de decisiones</div><div class="p-crit-line">${critDecisionGuide}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">IV. Comparación</div><div class="p-crit-line"><strong>Caso A:</strong> ${d.cmp.ga}</div><div class="p-crit-line"><strong>Caso B:</strong> ${d.cmp.gb}</div><div class="p-crit-line">${d.cmp.gr}</div></div>`;
  pR+=`<div class="p-sec" style="grid-column:1/-1;"><div class="p-ttl">V. Causas y efectos</div>${d.causes.map(it=>`<div class="p-crit-line"><strong>Causa:</strong> ${it.cause} → <strong>Efecto:</strong> ${it.guide}</div>`).join('')}${d.effects.map(it=>`<div class="p-crit-line"><strong>Efecto:</strong> ${it.effect} → <strong>Causa:</strong> ${it.guide}</div>`).join('')}</div>`;
  const doc=`<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><title>Simulacro de negociación Quién decide de verdad · Ruta del Poder Político · Forma ${forma}</title><style>*{margin:0;padding:0;box-sizing:border-box;}body{font-family:Arial,Helvetica,sans-serif;font-size:11pt;color:#111;background:#fff;padding:1mm 5mm;}.ph{margin-bottom:0.3rem;}.ph h2{font-size:11pt;font-weight:700;text-align:center;margin-bottom:0.2rem;}.ph-line{display:flex;align-items:baseline;gap:5px;margin-bottom:3px;}.ph-fill{flex:1;border-bottom:1px solid #555;min-height:12px;display:block;}.ph-m{display:inline-block;min-width:80px;border-bottom:1px solid #555;}.ph-s{display:inline-block;min-width:52px;border-bottom:1px solid #555;}.ph-xs{display:inline-block;min-width:36px;border-bottom:1px solid #555;}.ph-crit{font-size:9.5pt;text-align:center;color:#555;margin-top:0.1rem;}.sec-title{font-size:10.5pt;font-weight:700;padding:0.1rem 0.4rem;margin:0.2rem 0 0.1rem;display:flex;justify-content:space-between;align-items:center;border-left:4px solid #3b3a86;background:#ece9fb;color:#3b3a86;}.obt-row{display:flex;align-items:baseline;gap:4px;font-size:9.5pt;font-weight:700;font-style:italic;color:#3b3a86;}.obt-lbl{white-space:nowrap;}.obt-line{display:inline-block;min-width:50px;border-bottom:1.5px solid #3b3a86;height:12px;}.obt-pct{white-space:nowrap;}.crit-print-scenario{font-size:10.5pt;background:#ece9fb;border-left:3px solid #3b3a86;padding:0.2rem 0.5rem;margin:0.1rem 0 0.2rem;line-height:1.3;}.crit-print-q{font-size:10pt;font-weight:600;margin:0.15rem 0 0.08rem;line-height:1.25;}.ln{border-bottom:1px solid #111;min-height:12px;margin-bottom:2px;}.crit-compare-print-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.5rem;margin:0.15rem 0;}.crit-compare-print-box{font-size:9.5pt;background:#ece9fb;border-radius:4px;padding:0.25rem 0.4rem;line-height:1.25;}.crit-print-tbl{width:100%;border-collapse:collapse;font-size:9.5pt;margin-top:0.15rem;}.crit-print-tbl th,.crit-print-tbl td{border:1px solid #999;padding:0.3rem 0.45rem;text-align:left;height:30px;vertical-align:middle;}.crit-print-tbl th{background:#ece9fb;}.pauta-wrap{page-break-before:always;padding-top:0.4rem;}.p-head{border-bottom:2px solid #333;padding-bottom:0.3rem;margin-bottom:0.4rem;text-align:center;}.p-main{font-size:9.5pt;font-weight:700;}.p-sub{font-size:7pt;color:#c00;font-weight:700;margin:0.08rem 0;}.p-meta{font-size:7pt;color:#555;}.p-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.4rem 0.9rem;}.p-sec{border:1px solid #ccc;border-radius:4px;padding:0.3rem 0.45rem;}.p-ttl{font-size:8pt;font-weight:700;border-bottom:1px solid #ddd;padding-bottom:0.1rem;margin-bottom:0.18rem;}.p-crit-line{font-size:7.5pt;color:#007a00;margin-bottom:0.18rem;line-height:1.35;}.total-row{display:flex;align-items:baseline;justify-content:flex-start;margin-left:20%;gap:7px;font-size:11pt;font-weight:700;font-style:italic;margin-top:0.2rem;padding:0.1rem 0;color:#3b3a86;}.total-row .obt-line{min-width:80px;border-bottom:1.5px solid #3b3a86;}.forma-tag{font-size:7pt;color:#555;border:1px solid #bbb;padding:1px 5px;border-radius:3px;background:white;}.print-foot{position:fixed;bottom:2mm;left:0;right:0;display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:7.5pt;color:#111;background:#fff;padding:1px 3px;}.pf-item{display:inline-flex;align-items:center;gap:4px;}.pf-line{display:inline-block;width:26mm;border-bottom:1px solid #333;}.pf-box{display:inline-block;width:3.4mm;height:3.4mm;border:1px solid #333;}@media print{@page{size:letter portrait;margin:12.7mm;}}</style></head><body><div class="ph"><h2>Evaluación Competencial · Simulacro de negociación · Quién decide de verdad · Ruta del Poder Político · Autocapacitación Técnica</h2><div class="ph-line"><strong>Nombre:</strong><span class="ph-fill">&nbsp;</span><strong>Fecha:</strong><span class="ph-m">&nbsp;</span></div><div class="ph-line"><strong>Institución:</strong><span class="ph-fill">&nbsp;</span><strong>Grado y Sección:</strong><span class="ph-s">&nbsp;</span><strong>Nº Lista:</strong><span class="ph-xs">&nbsp;</span></div><p class="ph-crit">Valor total: 100 puntos · 5 secciones de 20 puntos</p></div>${s1}${s2}${s3}${s4}${s5}<div class="total-row"><span>Total, obtenido</span><span class="obt-line"></span><span>de 100</span></div><div class="pauta-wrap"><div class="p-head"><div class="p-main">✅ PAUTA: Simulacro de negociación · Quién decide de verdad · Ruta del Poder Político · Forma ${forma}</div><div class="p-sub">Documento exclusivo del docente · No distribuir al estudiante</div><div class="p-meta">Valor total: 100 pts | 5 secciones × 20 pts c/u, respuesta abierta, usar como guía de corrección</div></div><div class="p-grid">${pR}</div></div><div class="print-foot"><span class="pf-item"><strong>Nº de Evaluación temática realizada:</strong><span class="pf-line">&nbsp;</span></span><span class="pf-item"><strong>Evaluación con valor en el parcial</strong><span class="pf-box"></span></span><span class="pf-item"><strong>Evaluación solo de repaso</strong><span class="pf-box"></span></span><span class="forma-tag">Forma ${forma}</span></div></body></html>`;
  const win=window.open('','_blank','');
  if(!win){showToast('⚠️ Activa las ventanas emergentes para imprimir');return;}
  win.document.write(doc);win.document.close();setTimeout(()=>win.print(),400);
}

// ===================== LÍNEA DE TIEMPO INTERACTIVA =====================
const timelineData=[{"y":"1","icon":"🏫","label":"El centro educativo","text":"La escuela y su dirección. <strong>Decide:</strong> qué entra al aula, el horario, los permisos internos. <strong>Traba:</strong> cumpliendo a medias una orden que no quiere. <strong>Se le pide:</strong> un piloto en una sección, no un cambio de escuela entera."},{"y":"2","icon":"📍","label":"La dirección distrital","text":"El nivel más cercano al centro: acompaña y supervisa varias escuelas. <strong>Sirve para:</strong> presentar el proyecto a muchos directores a la vez y ganar el respaldo del que los visita todos los meses. <strong>Se le pide:</strong> espacio en su reunión."},{"y":"3","icon":"🗺️","label":"La dirección departamental","text":"Autoriza y coordina en todo el departamento. <strong>Es el nivel</strong> donde un proyecto deja de ser de una escuela y pasa a ser de una zona. <strong>Cuidado:</strong> una autorización de aquí sin el director del centro se cumple mal."},{"y":"4","icon":"🏛️","label":"La Secretaría","text":"El nivel nacional: fija la norma y el currículo. <strong>Da:</strong> legitimidad y alcance. <strong>No da:</strong> ejecución, que sigue dependiendo de cada centro. <strong>Riesgo:</strong> la adopción sin acuerdo de autoría deja el material sin nombre."},{"y":"5","icon":"🏘️","label":"La municipalidad","text":"Alcalde y corporación. No manda en el sistema educativo, pero tiene <strong>presupuesto propio, equipo y ganas de obra visible</strong>. <strong>Ojo:</strong> el presupuesto municipal se decide una vez al año; pedir fuera de esa ventana es pedir para el año siguiente."},{"y":"6","icon":"👨‍👩‍👧","label":"Los padres de familia","text":"Organizados en asociación o patronato. <strong>Poder real puro:</strong> pueden sostener un proyecto o hundirlo en una sola reunión. <strong>Regla:</strong> se les informa antes de decidir, nunca después, y menos si hay teléfonos o dinero de por medio."},{"y":"7","icon":"📅","label":"El calendario","text":"El año lectivo va de febrero a noviembre, con <strong>200 días de clase</strong> que cumplir por ley, y las autoridades electas cambian cada cuatro años. <strong>Consecuencia:</strong> el mismo permiso vale distinto según el mes en que llega. Se pide cuando sirve."}];
function initTimeline(){const track=document.getElementById('timelineTrack');if(!track)return;timelineData.forEach((d,i)=>{const b=document.createElement('button');b.className='tl-node';b.type='button';b.dataset.idx=i;b.innerHTML=`<span class="tl-dot">${d.icon}</span><span class="tl-year">${d.y}</span><span class="tl-label">${d.label}</span>`;b.onclick=()=>showTimeline(i);track.appendChild(b);});}
function showTimeline(i){const d=timelineData[i];document.querySelectorAll('.tl-node').forEach(n=>n.classList.remove('tl-active'));document.querySelector(`.tl-node[data-idx="${i}"]`).classList.add('tl-active');document.getElementById('tlInfoIcon').textContent=d.icon;document.getElementById('tlInfoText').innerHTML=`<strong>${d.y} · ${d.label}.</strong> ${d.text}`;document.getElementById('tlInfo').style.display='flex';sfx('click');}

// ===================== SIMULACIÓN: MÉTODO DE POPPER =====================
let methodRunning=false;
function startMethod(){if(methodRunning)return;methodRunning=true;sfx('click');document.getElementById('methodBtn').style.display='none';document.getElementById('methodBranch').classList.remove('show');document.getElementById('methodResult').innerHTML='';const steps=['ms1','ms2','ms3','ms4'];const arrows=['ma1','ma2','ma3'];steps.forEach(s=>document.getElementById(s).classList.remove('active','done'));arrows.forEach(a=>document.getElementById(a).classList.remove('active'));let i=0;function next(){if(i>0){document.getElementById(steps[i-1]).classList.remove('active');document.getElementById(steps[i-1]).classList.add('done');}if(i<steps.length){if(i>0)document.getElementById(arrows[i-1]).classList.add('active');document.getElementById(steps[i]).classList.add('active');sfx('ok');i++;setTimeout(next,900);}else{document.getElementById('methodBranch').classList.add('show');}}next();}
function resolveMethod(conInternet){sfx(conInternet?'ok':'no');document.getElementById('methodBranch').classList.remove('show');document.getElementById('ms4').classList.remove('active');document.getElementById('ms4').classList.add('done');const r=document.getElementById('methodResult');if(conInternet){r.innerHTML='<div class="method-step done" style="opacity:1;"><span class="ms-num">5</span><span class="ms-icon">🛡️</span><span class="ms-text"><strong>Pediste 24 horas:</strong> la presión se corta en seco y la conversación pasa del sentimiento a los números.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">📄</span><span class="ms-text"><strong>Al día siguiente decides tú:</strong> si el plazo era real, la oferta sigue en pie y ahora con condiciones tuyas. Si se cayó, la presión era el producto.</span></div>';}else{r.innerHTML='<div class="method-step done" style="opacity:1;border-color:var(--red);background:var(--red-gl);"><span class="ms-num">5</span><span class="ms-icon">✍️</span><span class="ms-text"><strong>Contestaste en caliente:</strong> el sí salió con la emoción alta y sin comparar nada.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">🔗</span><span class="ms-text"><strong>Y la coherencia lo amarra:</strong> ese sí pequeño se cobra después con uno más grande. No fue tonto: fue una decisión tomada en el peor momento posible.</span></div>';}methodRunning=false;document.getElementById('methodBtn').style.display='inline-flex';document.getElementById('methodBtn').textContent='🔄 Repetir simulación';sfx('fan');}

