const parteData={"centro":{"nombre":"El centro educativo","icon":"🏫","estructura":{"title":"Qué es","info":"• La escuela y su dirección<br>• El nivel donde el proyecto <strong>ocurre de verdad</strong><br>• Un director, a veces un subdirector, y el consejo de maestros"},"funcion":{"title":"Qué decide","info":"• Qué entra al aula y en qué horario<br>• Los permisos internos y el uso de los espacios<br>• Si algo se usa de verdad o solo se guarda"},"enfermedades":{"title":"Dónde traba","info":"• Cumpliendo a medias una orden que no quiere<br>• No avisando a los maestros de una capacitación<br>• Con el miedo a los teléfonos en el aula, que es real y hay que resolver"},"cuidados":{"title":"En el proyecto","info":"• Se entra con un piloto en una sola sección y una maestra que quiera<br>• Se ofrece la versión impresa: las fichas no necesitan teléfono<br>• Se vuelve en un mes con resultados que el director pueda mostrar"}},"departamental":{"nombre":"La departamental","icon":"🗺️","estructura":{"title":"Qué es","info":"• La dirección departamental de educación<br>• Coordina las direcciones distritales de su departamento<br>• Entre el centro y ella suele estar el nivel distrital o municipal"},"funcion":{"title":"Qué decide","info":"• Autoriza actividades y materiales en su territorio<br>• Convoca a directores y a docentes<br>• Es donde un proyecto pasa de una escuela a una zona"},"enfermedades":{"title":"Dónde traba","info":"• El oficio que se queda esperando firma<br>• El cambio de titular, que reinicia la conversación<br>• Autorizar sin comprometer a nadie a ejecutarlo"},"cuidados":{"title":"En el proyecto","info":"• Pedir un piloto acotado, no la adopción del departamento entero<br>• Proponer un docente enlace por zona para no cargar el soporte a una persona<br>• Salir con algo escrito, aunque sea el correo que resume la reunión"}},"municipalidad":{"nombre":"La municipalidad","icon":"🏘️","estructura":{"title":"Qué es","info":"• Alcalde y corporación municipal<br>• <strong>Fuera</strong> del sistema educativo, con presupuesto propio<br>• Decide su presupuesto una vez al año"},"funcion":{"title":"Qué decide","info":"• Gastos e inversiones del municipio<br>• Uso de equipo propio (impresión, transporte, espacios)<br>• Apoyos a actividades comunitarias y escolares"},"enfermedades":{"title":"Dónde traba","info":"• La petición vaga, que nadie sabe cómo aprobar<br>• El calendario: pedir fuera de la ventana presupuestaria<br>• El interés electoral, que quiere aparecer en todo lo que apoya"},"cuidados":{"title":"En el proyecto","info":"• Petición concreta y medible: «300 fichas para tres centros»<br>• Un beneficio que ellos puedan mostrar, sin que el proyecto quede marcado<br>• Es de las puertas más rápidas y de las menos usadas"}},"padres":{"nombre":"Los padres de familia","icon":"👨‍👩‍👧","estructura":{"title":"Qué es","info":"• Asociación de padres, patronato o consejo de la comunidad<br>• Sin cargo en el sistema y con <strong>enorme poder real</strong><br>• Se reúne pocas veces y decide mucho"},"funcion":{"title":"Qué decide","info":"• Si un proyecto tiene apoyo o sospecha en la comunidad<br>• Aportes voluntarios, jornadas, premios, alimentación<br>• Lo que se cuenta en el pueblo sobre la escuela"},"enfermedades":{"title":"Dónde traba","info":"• Cuando se entera después de que algo se decidió<br>• Con cualquier tema de teléfonos, dinero o datos de los niños<br>• Con un rumor, que viaja más rápido que cualquier oficio"},"cuidados":{"title":"En el proyecto","info":"• Se les informa <strong>antes</strong> de decidir, no después<br>• Se explica qué datos se guardan y qué no, en palabras simples<br>• Un grupo de padres a favor sostiene un proyecto más que un oficio"}}};
let labParte='centro',labAspecto='estructura';
function labShowParte(parteKey){labParte=parteKey;updateLabDisplay();document.querySelectorAll('.lab-cont-btn').forEach(b=>b.classList.remove('active-pri'));const btn=document.querySelector(`[data-parte="${parteKey}"]`);if(btn)btn.classList.add('active-pri');if(typeof sfx==='function')sfx('click');}
function labShowAspecto(aspectoKey){labAspecto=aspectoKey;updateLabDisplay();document.querySelectorAll('.lab-asp-btn').forEach(b=>b.classList.remove('active-sec'));const btn=document.querySelector(`[data-aspecto="${aspectoKey}"]`);if(btn)btn.classList.add('active-sec');if(typeof sfx==='function')sfx('click');}
function updateLabDisplay(){const data=parteData[labParte];const asp=data[labAspecto];document.getElementById('lab-sentence').innerHTML=`🦉 Explorando: <strong>${data.nombre}</strong> → <strong>${asp.title}</strong>`;document.getElementById('lab-display').innerHTML=`<div class="lab-cont-header">${data.icon} ${data.nombre}</div><div class="lab-asp-title">${asp.title}</div><div class="lab-asp-info">${asp.info}</div>`;}

// ===================== DIPLOMA =====================
function _diplPct(){return xp>=MXP?100:Math.round((xp/MXP)*100);}
function openDiploma(){sfx('fan');const pct=_diplPct();document.getElementById('diplPct').textContent=pct+'%';document.getElementById('diplBar').style.width=pct+'%';document.getElementById('diplDate').textContent='Fecha: '+new Date().toLocaleDateString('es-HN',{year:'numeric',month:'long',day:'numeric'});const msgs=['¡Sigue estudiando tu sistema!','¡Muy buen trabajo!','¡Excelente gestor en formación!','¡Sabes por dónde se mueve esto!','¡Estratega institucional!'];document.getElementById('diplMsg').textContent=msgs[Math.min(Math.floor(pct/25),4)];const stars=['⭐','⭐⭐','⭐⭐⭐'];document.getElementById('diplStars').textContent=stars[Math.min(Math.floor(pct/40),2)];const achTxt=unlockedAch.map(id=>ACHIEVEMENTS[id].icon+' '+ACHIEVEMENTS[id].label).join(' · ');document.getElementById('diplAch').textContent=achTxt||'Sigue completando secciones para desbloquear logros';document.getElementById('diplomaOverlay').classList.add('open');launchConfetti();}
function closeDiploma(){document.getElementById('diplomaOverlay').classList.remove('open');}
function updateDiplomaName(v){document.getElementById('diplName').textContent=v||'Estudiante';}
function shareWA(){const name=document.getElementById('diplName').textContent||'Estudiante';const pct=_diplPct();const msg='🏗️ ¡'+name+' completó la Etapa 1 de la Ruta del Poder Político (Quién decide de verdad)! 🏅 Progreso: '+pct+'% · ⚙️ policastsapien.com';window.open('https://wa.me/?text='+encodeURIComponent(msg),'_blank');}
async function captureDiploma(){if(typeof html2canvas==='undefined'){showToast('⚠️ Cargando... intenta de nuevo');return;}sfx('click');const card=document.querySelector('.diploma-card');const btn=document.querySelector('.diploma-actions .btn-pri');const toHide=[card.querySelector('.diploma-input'),card.querySelector('.diploma-actions'),card.querySelector('hr')];if(btn){btn.disabled=true;btn.textContent='⏳ Capturando...';}toHide.forEach(el=>{if(el)el.style.display='none';});let dataUrl='';try{const canvas=await html2canvas(card,{scale:2,useCORS:true,backgroundColor:'#ffffff'});toHide.forEach(el=>{if(el)el.style.display='';});dataUrl=canvas.toDataURL('image/png');const name=(document.getElementById('diplName').textContent||'Estudiante').replace(/\s+/g,'-');const fileName='constancia-'+name+'.png';const cap=window.Capacitor;if(cap&&cap.isNativePlatform&&cap.isNativePlatform()&&cap.Plugins?.Filesystem&&cap.Plugins?.Share){const base64Data=dataUrl.split(',')[1];const result=await cap.Plugins.Filesystem.writeFile({path:fileName,data:base64Data,directory:'CACHE'});await cap.Plugins.Share.share({url:result.uri,dialogTitle:'Guardar / Compartir Constancia'});}else{const a=document.createElement('a');a.href=dataUrl;a.download=fileName;a.click();}}catch(e){toHide.forEach(el=>{if(el)el.style.display='';});if(e.name!=='AbortError')showToast('⚠️ No se pudo guardar la constancia');}finally{if(btn){btn.disabled=false;btn.textContent='📷 Guardar foto';}}}

